import { createPrivateKey, sign } from "node:crypto";

type AppJwtOptions = Readonly<{
  /** GitHub recommends the client ID over the app ID for JWT `iss`. */
  clientId: string;
  /** PEM private key generated by GitHub for the app. */
  privateKey: string;
  /** Current Unix time in seconds; injectable for tests. */
  now?: number;
}>;

/**
 * GitHub accepts app JWTs for at most 10 minutes. See
 * https://docs.github.com/en/apps/creating-github-apps/authenticating-with-a-github-app/generating-a-json-web-token-jwt-for-a-github-app.
 */
const LIFETIME = 10 * 60;

/**
 * Backdate the token because GitHub rejects JWTs issued in the future, and the
 * runner clock may be slightly ahead.
 */
const CLOCK_DRIFT = 30;

/**
 * Captures both GitHub key formats: PKCS#1 (`RSA PRIVATE KEY`) and PKCS#8
 * (`PRIVATE KEY`).
 */
const PEM =
  /-{5}BEGIN (?<label>[ A-Z]+)-{5}(?<body>[^\-]*)-{5}END \k<label>-{5}/v;

/**
 * Rebuilds the PEM from only its label and base64 body. This tolerates escaped
 * line breaks, indentation, and the extra backslash that `act` can add before a
 * secret.
 */
function normalizePem(privateKey: string) {
  const match = PEM.exec(privateKey.replaceAll(String.raw`\n`, "\n"));

  if (match?.groups === undefined) {
    return privateKey;
  }

  const { label = "", body = "" } = match.groups;
  const lines = body.replaceAll(/\s/gv, "").match(/.{1,64}/gv) ?? [];

  return [
    `-----BEGIN ${label}-----`,
    ...lines,
    `-----END ${label}-----`,
    "",
  ].join("\n");
}

/**
 * Reads the app private key after normalizing the common ways it appears in
 * GitHub Actions secrets.
 */
function readPrivateKey(privateKey: string) {
  try {
    return createPrivateKey(normalizePem(privateKey));
  } catch (error) {
    throw new Error(
      `The private key of the GitHub App can't be read, expected a PEM key as GitHub generates it: ${error instanceof Error ? error.message : String(error)}`,
      { cause: error },
    );
  }
}

function encode(value: Readonly<Record<string, number | string>>) {
  return Buffer.from(JSON.stringify(value)).toString("base64url");
}

/**
 * Creates the RS256 JWT used to authenticate as the GitHub App itself before an
 * installation token exists.
 */
function createAppJwt({
  clientId,
  privateKey,
  now = Math.floor(Date.now() / 1000),
}: AppJwtOptions) {
  const key = readPrivateKey(privateKey);
  const issuedAt = now - CLOCK_DRIFT;
  const unsigned = `${encode({ alg: "RS256", typ: "JWT" })}.${encode({
    iat: issuedAt,
    exp: issuedAt + LIFETIME,
    iss: clientId,
  })}`;
  const signature = sign("sha256", Buffer.from(unsigned), key);

  return `${unsigned}.${signature.toString("base64url")}`;
}

export { createAppJwt };
